{
  "title": "Xikolo Quiz Management and Assessment System",
  "functional_domain": "Quiz Creation, Question Management, User Submissions, Grading, and Proctoring",
  "overview": "The Xikolo Quiz Management and Assessment System is a critical feature cluster enabling instructors to create, manage, and grade quizzes, while providing students with a robust platform for quiz submission and review. This functionality is distributed across the main Ruby on Rails application and dedicated microservices, including the `Quiz Service`, `Course Service`, and `Submission Service`.",
  "core_functionality": [
    {
      "name": "Quiz Creation and Management",
      "description": "Instructors can create and manage quizzes, questions, and answers.",
      "frontend_components": [
        {
          "name": "app/assets/teacher/items/quiz.ts",
          "role": "Orchestrates overall quiz item setup, including proctoring settings."
        },
        {
          "name": "app/assets/teacher/items/quiz-item.ts",
          "role": "Manages quiz properties (exercise type, time limits, allowed attempts) and dynamically adjusts UI."
        },
        {
          "name": "app/assets/teacher/items/quiz-questions.ts",
          "role": "Dynamically loads and switches question forms, initializes markdown editors (`initMarkdownEditorOnSelector`) and upload dropzones (`mdupload.scan`, `upload.scan`)."
        },
        {
          "name": "app/assets/teacher/items/quiz-edit.ts",
          "role": "Provides AJAX loading for question and answer editing forms using `fetch`."
        }
      ],
      "backend_components": [
        {
          "name": "QuizQuestionsController",
          "role": "Handles CRUD operations for quiz questions (MultipleChoice, MultipleAnswer, FreeText, Essay), manages positions, and ensures `plausible_question_type` (e.g., single correct answer for MCQs). Interacts with `Quiz Service` via `Xikolo::Quiz::Question` ACFS client models and `quiz_api` (Restify)."
        },
        {
          "name": "QuizAnswersController",
          "role": "Manages CRUD operations for quiz answers (TextAnswer, FreeTextAnswer) and their positioning."
        }
      ],
      "common_backend_logic": "Both `QuizQuestionsController` and `QuizAnswersController` enforce content editor permissions via `ensure_content_editor`."
    },
    {
      "name": "User Quiz Submissions",
      "description": "Students can start, submit, and review their quiz attempts.",
      "frontend_components": [
        {
          "name": "app/assets/course/items/quiz.ts",
          "role": "Facilitates navigation between different quiz submissions for a user. Also referred to as `QuizSubmissionNavigator`."
        }
      ],
      "backend_components": [
        {
          "name": "QuizSubmissionController",
          "role": "Handles starting new attempts (`new`), processing submitted answers (`create`), and displaying past submissions (`show`). Manages deadlines, time limits, allowed attempts, and proctoring. Interacts with `Quiz Service` (`Xikolo::Quiz::Quiz`) and `Submission Service` (`Xikolo::Submission::QuizSubmission`, `Xikolo::Submission::UserQuizAttempts`) via ACFS client models. Publishes `xikolo.submission.submission.create` event via `Msgr` (RabbitMQ) upon successful submission."
        },
        {
          "name": "QuizSubmissionSnapshotController",
          "role": "Provides an AJAX endpoint for saving partial quiz submissions."
        }
      ],
      "models_and_presenters": [
        {
          "name": "Quiz::Submission",
          "role": "Acts as a wrapper around responses from the `Quiz Service`, providing methods to access submission data and proctoring information. (Identified technical debt: should become a real ActiveRecord model)."
        },
        {
          "name": "Quiz::Submission::Proctoring",
          "role": "Integrates with `Proctoring::SmowlAdapter` to interpret and present proctoring results."
        },
        {
          "name": "QuizItemPresenter",
          "role": "Prepares data for the quiz item's introductory page, determining if a user can start, resume, or view results, and handles redirects based on quiz state and user permissions, considering proctoring status. (Identified technical debt: `TODO` for redirect logic)."
        }
      ]
    },
    {
      "name": "Quiz Result and Recap Display",
      "description": "Provides a comprehensive overview of quiz results and submitted answers.",
      "frontend_components": [
        {
          "name": "app/assets/quiz-recap/quiz-recap.ts",
          "role": "Responsible for fetching and rendering a comprehensive recap of quiz questions and answers, utilizing the `@openhpi/quiz-recap` external component. This is part of the `Course::QuizRecap` functionality."
        }
      ],
      "backend_components": [
        {
          "name": "QuizRecapController",
          "role": "Serves data for the quiz recap, retrieving questions and associated answers from the `Quiz Service` and enriching them with reference links from the `Course Service`."
        }
      ],
      "presenters": [
        {
          "name": "QuizResultPresenter",
          "role": "Formats submission data for display, including calculating percentages, generating historical submission graphs, and providing navigation labels for different attempts."
        },
        {
          "name": "QuizSubmissionProctoringPresenter",
          "role": "Translates raw proctoring results into user-friendly callout messages."
        }
      ]
    },
    {
      "name": "Proctoring Integration",
      "description": "Integrates external proctoring services into the quiz submission and review process.",
      "components_involved": [
        "`QuizSubmissionController` (checks enablement, handles `vendor_data`)",
        "`QuizItemPresenter` (considers proctoring status for quiz availability and redirects)",
        "`Quiz::Submission::Proctoring` model (processes results)",
        "`QuizSubmissionProctoringPresenter` (displays results)",
        "`Proctoring::SmowlAdapter` (specific proctoring service adapter)"
      ],
      "status_note": "Proctoring is currently unavailable for new quizzes."
    },
    {
      "name": "Regrading Capabilities",
      "description": "Administrative functionality for regrading quizzes.",
      "implementation": "Supported through `rake` tasks executed directly on the `xi-quiz` service (part of the `Quiz Service`).",
      "regrading_scenarios": [
        "`jackpot` (giving max points for a question)",
        "`remove_answer`",
        "`update_question` (recalculating points for a question)",
        "`update_all_questions` (for an entire quiz)",
        "`select_answer_for_all` (forcing a specific answer for all submissions)"
      ],
      "post_regrading_step": "A separate `rake regrading:just_update_course` task is required to update overall course results."
    }
  ],
  "architecture_and_inter_service_communication": {
    "description": "The system leverages a microservice architecture for distributed functionality.",
    "components": [
      {
        "name": "Main Ruby on Rails Application",
        "role": "Hosts frontend assets, controllers, models, and presenters."
      },
      {
        "name": "Quiz Service (Microservice)",
        "role": "A dedicated service managing core quiz entities (`Quiz`, `Question`, `Answer`, `QuizSubmission`) and providing APIs. Also hosts `Regrading Rake Tasks`."
      },
      {
        "name": "Course Service (Microservice)",
        "role": "Provides course-related data, including reference links for quiz recaps."
      },
      {
        "name": "Submission Service (Microservice)",
        "role": "Handles submission-related logic and persistence."
      }
    ],
    "key_interactions": [
      {
        "type": "Synchronous (HTTP/REST)",
        "details": "Main application communicates with `Quiz Service` and `Course Service` using `Restify` via `Xikolo.api(:quiz)` and `Xikolo.api(:course)` calls, abstracted through `Acfs` client models (e.g., `Xikolo::Quiz::Question`, `Xikolo::Quiz::Quiz`, `Xikolo::Submission::QuizSubmission`, `Xikolo::Submission::UserQuizAttempts`)."
      },
      {
        "type": "Asynchronous (Message Queue)",
        "details": "New quiz submissions trigger an `xikolo.submission.submission.create` event published via `Msgr` (RabbitMQ) to the `Submission Service`."
      },
      {
        "type": "Direct Service Interaction",
        "details": "Regrading `rake` tasks are executed directly on the `xi-quiz` service."
      }
    ]
  },
